	CONSTRAINT "idp_authorizations_family_id_fkey" FOREIGN KEY ("family_id") REFERENCES "idp_families" ("id") ON DELETE CASCADE
) STRICT;

CREATE UNIQUE INDEX "idp_authorizations_consent_hash_key" ON "idp_authorizations" ("consent_hash");

CREATE UNIQUE INDEX "idp_authorizations_code_hash_key" ON "idp_authorizations" ("code_hash");

CREATE INDEX "idp_authorizations_expires_at_idx" ON "idp_authorizations" ("expires_at");

CREATE TABLE "idp_clients" (
	"id" BLOB NOT NULL CHECK (length("id") = 16),
	"client_id" TEXT NOT NULL CHECK (length("client_id") <= 64),
	"name" TEXT NOT NULL,
	"auth_method" TEXT NOT NULL,
	"secret_hash" BLOB,
	"jwks" TEXT CHECK (json_valid("jwks")),
	"grant_types" TEXT NOT NULL CHECK (json_valid("grant_types")),
	"id_token_alg" TEXT NOT NULL,
	"redirect_uris" TEXT NOT NULL CHECK (json_valid("redirect_uris")),
	"post_logout_redirect_uris" TEXT NOT NULL CHECK (json_valid("post_logout_redirect_uris")),
	"scopes" TEXT NOT NULL CHECK (json_valid("scopes")),
	"first_party" INTEGER NOT NULL CHECK ("first_party" IN (0, 1)),
	"introspection" INTEGER NOT NULL CHECK ("introspection" IN (0, 1)),
	"subject_salt" BLOB NOT NULL,
	"owner_id" BLOB CHECK (length("owner_id") = 16),
	"dpop_bound" INTEGER NOT NULL DEFAULT 0 CHECK ("dpop_bound" IN (0, 1)),
	"registration_hash" BLOB,
	"created_at" TEXT NOT NULL,
	CONSTRAINT "idp_clients_pkey" PRIMARY KEY ("id"),
	CONSTRAINT "idp_clients_owner_id_fkey" FOREIGN KEY ("owner_id") REFERENCES "auth_accounts" ("id") ON DELETE CASCADE,
	CONSTRAINT "idp_clients_name_length" CHECK (length("name") >= 1 AND length("name") <= 100),
	CONSTRAINT "idp_clients_auth_method_values" CHECK ("auth_method" IN ('none', 'client_secret_basic', 'client_secret_post', 'private_key_jwt')),
	CONSTRAINT "idp_clients_id_token_alg_values" CHECK ("id_token_alg" IN ('ES256', 'RS256'))
) STRICT;

CREATE UNIQUE INDEX "idp_clients_client_id_key" ON "idp_clients" ("client_id");

CREATE UNIQUE INDEX "idp_clients_registration_hash_key" ON "idp_clients" ("registration_hash");

CREATE INDEX "idp_clients_owner_id_idx" ON "idp_clients" ("owner_id");

CREATE TABLE "idp_device_codes" (
	"id" BLOB NOT NULL CHECK (length("id") = 16),
	"client_id" BLOB NOT NULL CHECK (length("client_id") = 16),
	"device_hash" BLOB NOT NULL,
	"user_code_hash" BLOB NOT NULL,
	"scopes" TEXT NOT NULL CHECK (json_valid("scopes")),
	"account_id" BLOB CHECK (length("account_id") = 16),
	"auth_time" TEXT,
	"approved" INTEGER CHECK ("approved" IN (0, 1)),
	"interval" INTEGER NOT NULL CHECK ("interval" BETWEEN -2147483648 AND 2147483647),
	"polled_at" TEXT,
	"expires_at" TEXT NOT NULL,
	"used_at" TEXT,
	"family_id" BLOB CHECK (length("family_id") = 16),
	"created_at" TEXT NOT NULL,
	CONSTRAINT "idp_device_codes_pkey" PRIMARY KEY ("id"),
	CONSTRAINT "idp_device_codes_client_id_fkey" FOREIGN KEY ("client_id") REFERENCES "idp_clients" ("id") ON DELETE CASCADE,
	CONSTRAINT "idp_device_codes_account_id_fkey" FOREIGN KEY ("account_id") REFERENCES "auth_accounts" ("id") ON DELETE CASCADE,
	CONSTRAINT "idp_device_codes_family_id_fkey" FOREIGN KEY ("family_id") REFERENCES "idp_families" ("id") ON DELETE CASCADE,
	CONSTRAINT "idp_device_codes_interval_range" CHECK ("interval" >= 1)
) STRICT;

CREATE UNIQUE INDEX "idp_device_codes_device_hash_key" ON "idp_device_codes" ("device_hash");

CREATE UNIQUE INDEX "idp_device_codes_user_code_hash_key" ON "idp_device_codes" ("user_code_hash");

CREATE INDEX "idp_device_codes_expires_at_idx" ON "idp_device_codes" ("expires_at");

CREATE TABLE "idp_dpop_proofs" (
	"id" BLOB NOT NULL CHECK (length("id") = 16),
	"jti_hash" BLOB NOT NULL,
	"expires_at" TEXT NOT NULL,
	CONSTRAINT "idp_dpop_proofs_pkey" PRIMARY KEY ("id")
) STRICT;

CREATE UNIQUE INDEX "idp_dpop_proofs_jti_hash_key" ON "idp_dpop_proofs" ("jti_hash");

CREATE INDEX "idp_dpop_proofs_expires_at_idx" ON "idp_dpop_proofs" ("expires_at");

CREATE TABLE "idp_families" (
	"id" BLOB NOT NULL CHECK (length("id") = 16),
	"grant_id" BLOB CHECK (length("grant_id") = 16),
	"account_id" BLOB CHECK (length("account_id") = 16),
	"client_id" BLOB NOT NULL CHECK (length("client_id") = 16),
	"scopes" TEXT NOT NULL CHECK (json_valid("scopes")),
	"id_token_claims" TEXT NOT NULL CHECK (json_valid("id_token_claims")),
	"auth_time" TEXT NOT NULL,
	"expires_at" TEXT NOT NULL,
	"revoked_at" TEXT,
	"jkt" TEXT CHECK (length("jkt") <= 64),
	"created_at" TEXT NOT NULL,
	CONSTRAINT "idp_families_pkey" PRIMARY KEY ("id"),
	CONSTRAINT "idp_families_grant_id_fkey" FOREIGN KEY ("grant_id") REFERENCES "idp_grants" ("id") ON DELETE CASCADE,
	CONSTRAINT "idp_families_account_id_fkey" FOREIGN KEY ("account_id") REFERENCES "auth_accounts" ("id") ON DELETE CASCADE,
	CONSTRAINT "idp_families_client_id_fkey" FOREIGN KEY ("client_id") REFERENCES "idp_clients" ("id") ON DELETE CASCADE
) STRICT;

CREATE INDEX "idp_families_account_id_idx" ON "idp_families" ("account_id");

CREATE INDEX "idp_families_expires_at_idx" ON "idp_families" ("expires_at");

CREATE TABLE "idp_grants" (
	"id" BLOB NOT NULL CHECK (length("id") = 16),
	"account_id" BLOB NOT NULL CHECK (length("account_id") = 16),
	"client_id" BLOB NOT NULL CHECK (length("client_id") = 16),
	"scopes" TEXT NOT NULL CHECK (json_valid("scopes")),
	"created_at" TEXT NOT NULL,
	"updated_at" TEXT NOT NULL,
	"last_used_at" TEXT,
	CONSTRAINT "idp_grants_pkey" PRIMARY KEY ("id"),
	CONSTRAINT "idp_grants_account_id_fkey" FOREIGN KEY ("account_id") REFERENCES "auth_accounts" ("id") ON DELETE CASCADE,
	CONSTRAINT "idp_grants_client_id_fkey" FOREIGN KEY ("client_id") REFERENCES "idp_clients" ("id") ON DELETE CASCADE
) STRICT;

CREATE UNIQUE INDEX "idp_grants_account_id_client_id_key" ON "idp_grants" ("account_id", "client_id");

CREATE TABLE "idp_pushed_requests" (
	"id" BLOB NOT NULL CHECK (length("id") = 16),
	"client_id" BLOB NOT NULL CHECK (length("client_id") = 16),
	"handle_hash" BLOB NOT NULL,
	"request" TEXT NOT NULL CHECK (json_valid("request")),
	"expires_at" TEXT NOT NULL,
	"created_at" TEXT NOT NULL,
	CONSTRAINT "idp_pushed_requests_pkey" PRIMARY KEY ("id"),
	CONSTRAINT "idp_pushed_requests_client_id_fkey" FOREIGN KEY ("client_id") REFERENCES "idp_clients" ("id") ON DELETE CASCADE
) STRICT;

CREATE UNIQUE INDEX "idp_pushed_requests_handle_hash_key" ON "idp_pushed_requests" ("handle_hash");

CREATE INDEX "idp_pushed_requests_expires_at_idx" ON "idp_pushed_requests" ("expires_at");

CREATE TABLE "idp_refresh_tokens" (
	"id" BLOB NOT NULL CHECK (length("id") = 16),
	"family_id" BLOB NOT NULL CHECK (length("family_id") = 16),
	"token_hash" BLOB NOT NULL,
	"used_at" TEXT,
	"created_at" TEXT NOT NULL,
	CONSTRAINT "idp_refresh_tokens_pkey" PRIMARY KEY ("id"),
	CONSTRAINT "idp_refresh_tokens_family_id_fkey" FOREIGN KEY ("family_id") REFERENCES "idp_families" ("id") ON DELETE CASCADE
) STRICT;

CREATE UNIQUE INDEX "idp_refresh_tokens_token_hash_key" ON "idp_refresh_tokens" ("token_hash");

CREATE TABLE "idp_signing_keys" (
	"id" BLOB NOT NULL CHECK (length("id") = 16),
	"kid" TEXT NOT NULL CHECK (length("kid") <= 64),
	"algorithm" TEXT NOT NULL,
	"derived_from" TEXT CHECK (length("derived_from") <= 64),
	"x" TEXT CHECK (length("x") <= 64),
	"y" TEXT CHECK (length("y") <= 64),
	"n" TEXT CHECK (length("n") <= 1400),
	"e" TEXT CHECK (length("e") <= 16),
	"retires_at" TEXT NOT NULL,
	"expires_at" TEXT NOT NULL,
	"created_at" TEXT NOT NULL,
	CONSTRAINT "idp_signing_keys_pkey" PRIMARY KEY ("id"),
	CONSTRAINT "idp_signing_keys_algorithm_values" CHECK ("algorithm" IN ('ES256', 'RS256'))
) STRICT;

CREATE UNIQUE INDEX "idp_signing_keys_kid_key" ON "idp_signing_keys" ("kid");

CREATE TABLE "live_changes" (
	"seq" INTEGER NOT NULL,
	"txid" INTEGER,
	"version" INTEGER,
	"table_name" TEXT NOT NULL,
	"op" TEXT NOT NULL,
	"key" TEXT NOT NULL CHECK (json_valid("key")),
	"old" TEXT CHECK (json_valid("old")),
	"new" TEXT CHECK (json_valid("new")),
	"changed" TEXT NOT NULL CHECK (json_valid("changed")),
	CONSTRAINT "live_changes_pkey" PRIMARY KEY ("seq"),
	CONSTRAINT "live_changes_op_values" CHECK ("op" IN ('I', 'U', 'D'))
) STRICT;

CREATE INDEX "live_changes_txid_idx" ON "live_changes" ("txid");

CREATE INDEX "live_changes_version_idx" ON "live_changes" ("version");

CREATE TABLE "live_commits" (
	"version" INTEGER NOT NULL,
	"txid" INTEGER,
	"committed_at" TEXT NOT NULL,
	"actor" BLOB CHECK (length("actor") = 16),
