	"title" TEXT NOT NULL CHECK (length("title") <= 255),
	"body" TEXT NOT NULL CHECK (length("body") <= 4000),
	"link" TEXT CHECK (length("link") <= 2000),
	"action" TEXT CHECK (json_valid("action")),
	"kind" TEXT NOT NULL CHECK (length("kind") <= 32),
	"read_at" TEXT,
	"created_at" TEXT NOT NULL,
	CONSTRAINT "rpc_inbox_pkey" PRIMARY KEY ("id")
) STRICT;

CREATE INDEX "rpc_inbox_account_created_at_idx" ON "rpc_inbox" ("account", "created_at");

CREATE TABLE "rpc_jobs" (
	"id" BLOB NOT NULL CHECK (length("id") = 16),
	"key" TEXT CHECK (length("key") <= 255),
	"name" TEXT NOT NULL CHECK (length("name") <= 255),
	"queue" TEXT NOT NULL CHECK (length("queue") <= 255),
	"arguments" TEXT NOT NULL CHECK (json_valid("arguments")),
	"owner" TEXT NOT NULL CHECK (length("owner") <= 64),
	"viewer" TEXT NOT NULL CHECK (length("viewer") <= 64),
	"visibility" TEXT NOT NULL,
	"serial_key" TEXT CHECK (length("serial_key") <= 512),
	"state" TEXT NOT NULL,
	"attempts" INTEGER NOT NULL,
	"max_attempts" INTEGER NOT NULL,
	"priority" INTEGER NOT NULL CHECK ("priority" BETWEEN -2147483648 AND 2147483647),
	"run_at" TEXT NOT NULL,
	"deadline_at" TEXT,
	"started_at" TEXT,
	"finished_at" TEXT,
	"locked_until" TEXT,
	"result" TEXT CHECK (json_valid("result")),
	"error" TEXT CHECK (length("error") <= 2000),
	"progress" TEXT CHECK (length("progress") <= 500),
	"fraction" REAL,
	"steps" TEXT NOT NULL CHECK (json_valid("steps")),
	"cancel_requested" INTEGER NOT NULL CHECK ("cancel_requested" IN (0, 1)),
	"failure_pending" INTEGER NOT NULL CHECK ("failure_pending" IN (0, 1)),
	"created_at" TEXT NOT NULL,
	CONSTRAINT "rpc_jobs_pkey" PRIMARY KEY ("id"),
	CONSTRAINT "rpc_jobs_visibility_values" CHECK ("visibility" IN ('owner', 'signed_in', 'everyone')),
	CONSTRAINT "rpc_jobs_state_values" CHECK ("state" IN ('pending', 'running', 'done', 'failed', 'cancelled'))
) STRICT;

CREATE UNIQUE INDEX "rpc_jobs_key_key" ON "rpc_jobs" ("key");

CREATE INDEX "rpc_jobs_state_run_at_idx" ON "rpc_jobs" ("state", "run_at");

CREATE INDEX "rpc_jobs_locked_until_idx" ON "rpc_jobs" ("locked_until");

CREATE INDEX "rpc_jobs_queue_state_idx" ON "rpc_jobs" ("queue", "state");

CREATE INDEX "rpc_jobs_serial_key_state_idx" ON "rpc_jobs" ("serial_key", "state");

CREATE INDEX "rpc_jobs_finished_at_idx" ON "rpc_jobs" ("finished_at");

CREATE TABLE "rpc_receipts" (
	"id" BLOB NOT NULL CHECK (length("id") = 16),
	"owner" TEXT NOT NULL CHECK (length("owner") <= 255),
	"request_id" TEXT NOT NULL CHECK (length("request_id") <= 255),
	"operation" TEXT NOT NULL CHECK (length("operation") <= 255),
	"arguments" TEXT NOT NULL CHECK (length("arguments") <= 64),
