CREATE TRIGGER "live_accounts_delete" AFTER DELETE ON "accounts" FOR EACH ROW BEGIN
	INSERT INTO "live_changes" ("seq", "txid", "version", "table_name", "op", "key", "old", "new", "changed") VALUES ((SELECT coalesce(max("seq"), 0) + 1 FROM "live_changes"), NULL, NULL, 'accounts', 'D', json_array(CASE WHEN OLD."id" IS NULL THEN NULL ELSE lower(hex(OLD."id")) END), json_object('id', CASE WHEN OLD."id" IS NULL THEN NULL ELSE lower(hex(OLD."id")) END, 'display_name', OLD."display_name", 'created_at', OLD."created_at", 'updated_at', OLD."updated_at"), NULL, '[]');
END;

