	INSERT INTO "live_changes" ("seq", "txid", "version", "table_name", "op", "key", "old", "new", "changed") VALUES ((SELECT coalesce(max("seq"), 0) + 1 FROM "live_changes"), NULL, NULL, 'accounts', 'U', json_array(CASE WHEN NEW."id" IS NULL THEN NULL ELSE lower(hex(NEW."id")) END), json_object('id', CASE WHEN OLD."id" IS NULL THEN NULL ELSE lower(hex(OLD."id")) END, 'display_name', OLD."display_name", 'created_at', OLD."created_at", 'updated_at', OLD."updated_at"), json_object('id', CASE WHEN NEW."id" IS NULL THEN NULL ELSE lower(hex(NEW."id")) END, 'display_name', NEW."display_name", 'created_at', NEW."created_at", 'updated_at', NEW."updated_at"), (SELECT json_group_array("value") FROM json_each(json_array(CASE WHEN OLD."created_at" IS NOT NEW."created_at" THEN 'created_at' END, CASE WHEN OLD."display_name" IS NOT NEW."display_name" THEN 'display_name' END, CASE WHEN OLD."id" IS NOT NEW."id" THEN 'id' END, CASE WHEN OLD."updated_at" IS NOT NEW."updated_at" THEN 'updated_at' END)) WHERE "type" <> 'null'));
END;

