eriod_key' END, CASE WHEN OLD."rejection_code" IS NOT NEW."rejection_code" THEN 'rejection_code' END, CASE WHEN OLD."reward_outcome" IS NOT NEW."reward_outcome" THEN 'reward_outcome' END, CASE WHEN OLD."started_at" IS NOT NEW."started_at" THEN 'started_at' END, CASE WHEN OLD."status" IS NOT NEW."status" THEN 'status' END, CASE WHEN OLD."submitted_at" IS NOT NEW."submitted_at" THEN 'submitted_at' END, CASE WHEN OLD."updated_at" IS NOT NEW."updated_at" THEN 'updated_at' END, CASE WHEN OLD."verification_score" IS NOT NEW."verification_score" THEN 'verification_score' END, CASE WHEN OLD."verified_at" IS NOT NEW."verified_at" THEN 'verified_at' END)) WHERE "type" <> 'null'));
